Let's follow the pattern I've shown you for `Open_RunningProcess_ReturnsValidHandle`:

- obtain process in two different ways
- have one assert
- ensure it's disposed in the finally block

```suggestion

            Process? found = null;
            try
            {
                if (tryGet)
                {
                    Assert.True(Process.TryGetProcessById(process.Id, out found););
                }
                else
                {
                    found = Process.GetProcessById(process.Id);
                }

                Assert.NotNull(found);
                Assert.Equal(process.Id, found.Id);
                Assert.Equal(process.ProcessName, found.ProcessName);

                found.Kill();
                found.WaitForExit();      
            }
            finally
            {
                process.Kill();
                process.WaitForExit();
                found?.Dispose();
            }
